window.docContents[127].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Weakening":{"contents":"The weakening lemma is proved as in pure STLC, with the exception of the sub case,\nwhich requires a manual use of the sub rule.\n\ntheorem weakening {Γ Γ' : Context} {t : Tm} {τ: Ty}\n    (hi : Γ ⊆ Γ')\n    (ht : <{ ~Γ ⊢ ~t ⦂ ~τ }>) :\n     <{ ~Γ' ⊢ ~t ⦂ ~τ }> := by\n  induction ht generalizing Γ' with (try apply_rules [PartialMap.update_subset] using StlcSubTyping)\n  | sub Γ t₁ τ₁ τ₂ ht hs ih =>\n    apply HasType.sub <;> solve_by_elim using StlcSubTyping\n\ntheorem weakening_empty {Γ : Context} {t : Tm} {τ: Ty}\n    (ht :<{ ∅ ⊢ ~t ⦂ ~τ }>) :\n    <{ ~Γ ⊢ ~t ⦂ ~τ }> := by\n  apply weakening _ ht\n  intro _ _ h\n  rw [PartialMap.getElem_empty] at h\n  contradiction\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Properties","header":"8.3.5. Weakening","id":"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Weakening"}});